/* llm-entity-extraction — experiment log viewer.
 * Dependency-free, hash-routed, data files under ./data/ generated by
 * scripts/site/build_site.py.
 */
"use strict";

const state = { meta: null, index: [], detail: null, runId: null };

const $ = (sel) => document.querySelector(sel);

function esc(v) {
  return String(v ?? "")
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#39;");
}

const fmt = {
  int: (n) => (n == null ? "—" : Number(n).toLocaleString("en-US")),
  pct: (v) => (v == null ? "—" : `${(v * 100).toFixed(1)}%`),
  score: (v) => (v == null ? "—" : v.toFixed(4)),
  date: (iso) => {
    if (!iso) return "—";
    const d = new Date(iso);
    return isNaN(d) ? iso : d.toISOString().replace("T", " ").slice(0, 16) + " UTC";
  },
  money: (v) =>
    v == null || v === 0 ? "—" : `$${Number(v).toLocaleString("en-US", { maximumFractionDigits: 2 })}`,
  tokens: (v) => (v == null ? "—" : fmt.int(v)),
  cost: (v) => (v == null || v === 0 ? "—" : `$${v.toFixed(4)}`),
};

function barClass(v) {
  if (v >= 0.85) return "good";
  if (v >= 0.6) return "warn";
  return "bad";
}

function barHtml(v, width = 64) {
  if (v == null) return '<span class="faint">—</span>';
  const pct = Math.max(0, Math.min(1, v)) * 100;
  return `<span class="bar ${barClass(v)}"><i style="width:${pct.toFixed(1)}%"></i></span>`;
}

function taskTag(task) {
  const label = (task || "").replace("_", " ");
  const cls = task?.startsWith("contract")
    ? "extraction"
    : task?.startsWith("chained")
      ? "chained"
      : task?.startsWith("subtype")
        ? "subtype"
        : "";
  return `<span class="task-tag ${cls}">${esc(label)}</span>`;
}

function headlineCell(h) {
  if (!h || h.value == null) return '<span class="faint">—</span>';
  return `<span class="score-cell"><span class="label">${esc(h.label || "")}</span>` +
    `<strong>${fmt.score(h.value)}</strong>${barHtml(h.value)}` +
    (h.detail ? `<div class="faint" style="font-size:11.5px">${esc(h.detail)}</div>` : "") +
    `</span>`;
}

/* ---------- routing ---------- */

async function fetchJson(url) {
  const res = await fetch(url);
  if (!res.ok) throw new Error(`${url} -> ${res.status}`);
  return res.json();
}

function parseHash() {
  const m = window.location.hash.match(/^#\/run\/(\d+)/);
  if (m) return { view: "run", id: Number(m[1]) };
  return { view: "index" };
}

async function route() {
  const r = parseHash();
  if (r.view === "run") {
    await renderRun(r.id);
  } else {
    await renderIndex();
  }
}

/* ---------- index view ---------- */

function statCards() {
  const m = state.meta;
  const best = m.best_per_task || {};
  const cards = [
    { k: "Runs", v: fmt.int(m.run_count), d: Object.entries(m.tasks || {}).map(([t, n]) => `${n} ${t.replace("_", " ")}`).join(" · ") },
    { k: "Documents evaluated", v: fmt.int(m.n_rows), d: `${fmt.int(m.n_ok)} ok · ${fmt.int(m.n_error)} errors` },
    { k: "Total tokens", v: fmt.tokens(m.total_tokens) },
    { k: "Models", v: fmt.int(Object.keys(m.models || {}).length), d: Object.keys(m.models || {}).join(", ") },
  ];
  for (const task of Object.keys(best).sort()) {
    cards.push({
      k: `Best · ${task.replace("_", " ")}`,
      v: fmt.score(best[task].value),
      d: best[task].label,
      best: true,
      href: `#/run/${best[task].run_id}`,
    });
  }
  return cards
    .map(
      (c) =>
        `<div class="stat ${c.best ? "best" : ""}">
           <div class="k">${esc(c.k)}</div>
           <div class="v">${esc(c.v)}</div>
           ${c.d ? `<div class="d">${esc(c.d)}</div>` : ""}
         </div>`
    )
    .join("");
}

function options(rows, get, placeholder) {
  const values = [...new Set(rows.map(get))].filter(Boolean).sort();
  return (
    `<option value="">${placeholder}</option>` +
    values.map((v) => `<option>${esc(v)}</option>`).join("")
  );
}

function indexTable(rows) {
  if (!rows.length) return '<div class="empty">No runs match the current filters.</div>';
  const sortKey = state.sortKey || "id";
  const dir = state.sortDir === "desc" ? -1 : 1;
  const sorted = [...rows].sort((a, b) => {
    const va = a[sortKey], vb = b[sortKey];
    if (sortKey === "headline") return ((va?.value ?? -1) - (vb?.value ?? -1)) * dir;
    if (sortKey === "total_tokens") return ((va ?? -1) - (vb ?? -1)) * dir;
    return String(va ?? "").localeCompare(String(vb ?? "")) * dir;
  });
  const cols = [
    ["#", "id", true], ["Experiment", "experiment_name"], ["Task", "task"],
    ["Model", "model"], ["Prompt(s)", "prompts"], ["Score", "headline"],
    ["Rows", "n_rows", true], ["Tokens", "total_tokens", true],
    ["Run at", "timestamp"],
  ];
  const arrow = (k) => (state.sortKey === k ? `<span class="arrow">${state.sortDir === "asc" ? "▲" : "▼"}</span>` : "");
  const head = cols
    .map(([label, key, num]) => `<th class="${num ? "num" : ""}" data-key="${key}">${label}${arrow(key)}</th>`)
    .join("");
  const body = sorted
    .map((r) => {
      const ts = r.timestamp;
      return `<tr data-id="${r.id}">
        <td class="num faint">${r.id}</td>
        <td><span class="mono">${esc(r.experiment_name)}</span>
            ${r.git ? `<div class="faint" style="font-size:11px">@${esc(r.git.commit)}</div>` : ""}</td>
        <td>${taskTag(r.task)}</td>
        <td class="mono">${esc(r.model)}</td>
        <td class="mono">${esc(r.prompts)}</td>
        <td>${headlineCell(r.headline)}</td>
        <td class="num">${fmt.int(r.n_rows)}</td>
        <td class="num">${fmt.tokens(r.total_tokens)}</td>
        <td class="num faint" style="white-space:nowrap">${fmt.date(ts)}</td>
      </tr>`;
    })
    .join("");
  return `<div class="table-wrap"><table class="data"><thead><tr>${head}</tr></thead><tbody>${body}</tbody></table></div>`;
}

function applyFilters() {
  const q = ($("#q").value || "").toLowerCase();
  const task = $("#f-task").value;
  const model = $("#f-model").value;
  const prompt = $("#f-prompt").value;
  const rows = state.index.filter(
    (r) =>
      (!q ||
        [r.experiment_name, r.model, r.prompts, r.task, r.git?.commit]
          .join(" ")
          .toLowerCase()
          .includes(q)) &&
      (!task || r.task === task) &&
      (!model || r.model === model) &&
      (!prompt || r.prompts === prompt)
  );
  $("#run-count").textContent = `${rows.length} of ${state.index.length} runs`;
  $("#index-table").innerHTML = indexTable(rows);
}

async function renderIndex() {
  if (!state.meta) {
    const [meta, index] = await Promise.all([
      fetchJson("data/meta.json"),
      fetchJson("data/index.json"),
    ]);
    state.meta = meta;
    state.index = index;
  }
  if (state.sortKey === undefined) {
    state.sortKey = "id";
    state.sortDir = "desc";
  }
  $("#view").innerHTML = `
    <div class="stats">${statCards()}</div>
    <div class="card">
      <h2>Runs</h2>
      <div class="filters">
        <input type="search" id="q" placeholder="Search experiment, prompt, model, commit…" />
        <select id="f-task"></select>
        <select id="f-model"></select>
        <select id="f-prompt"></select>
        <span class="count" id="run-count"></span>
      </div>
      <div id="index-table"></div>
    </div>`;
  $("#f-task").innerHTML = options(state.index, (r) => r.task, "All tasks");
  $("#f-model").innerHTML = options(state.index, (r) => r.model, "All models");
  $("#f-prompt").innerHTML = options(state.index, (r) => r.prompts, "All prompts");
  for (const id of ["q", "f-task", "f-model", "f-prompt"]) {
    $("#" + id).addEventListener("input", applyFilters);
  }
  $("#index-table").addEventListener("click", (e) => {
    const tr = e.target.closest("tr[data-id]");
    if (tr) window.location.hash = `#/run/${tr.dataset.id}`;
  });
  $("#index-table").addEventListener("click", (e) => {
    const th = e.target.closest("th[data-key]");
    if (!th) return;
    const key = th.dataset.key;
    if (state.sortKey === key) {
      state.sortDir = state.sortDir === "asc" ? "desc" : "asc";
    } else {
      state.sortKey = key;
      state.sortDir = key === "id" || key === "n_rows" || key === "total_tokens" ? "desc" : "asc";
    }
    applyFilters();
  });
  applyFilters();
}

/* ---------- run detail view ---------- */

function kvRows(obj) {
  return Object.entries(obj || {})
    .map(([k, v]) => `<tr><td class="k">${esc(k)}</td><td class="v">${esc(v)}</td></tr>`)
    .join("");
}

function kvRowsTyped(obj) {
  return Object.entries(obj || {})
    .map(([k, v]) => {
      let html;
      if (typeof v === "boolean") html = v ? "yes" : "no";
      else if (typeof v === "number") html = v.toFixed(4).replace(/0+$/, "").replace(/\.$/, "");
      else if (v === null || v === undefined) html = "—";
      else html = esc(v);
      return `<tr><td class="k">${esc(k)}</td><td class="v">${html}</td></tr>`;
    })
    .join("");
}

function scoreRows(obj) {
  return Object.entries(obj || {})
    .map(
      ([name, v]) =>
        `<div class="score-row"><div class="name">${esc(name)}</div>
         <div class="track"><i class="${barClass(v)}" style="width:${(Math.max(0, Math.min(1, v)) * 100).toFixed(1)}%"></i></div>
         <div class="value">${fmt.score(v)}</div></div>`
    )
    .join("");
}

function kvCard(title, body, flush = false) {
  return `<div class="card"><h2>${esc(title)}</h2><div class="body${flush ? " flush" : ""}">${body}</div></div>`;
}

function resultsTable(record) {
  const task = record.task;
  const rows = (record.results || [])
    .map((res, i) => {
      const sorter = res.sorter || {};
      const detail = task === "subtype_classification"
        ? `<tr class="insight-row" data-expand="${i}" hidden>
             <td colspan="5">
               <div class="kv" style="max-width:760px">${kvRowsTyped({
                 "doc type": sorter.doc_type,
                 "expected subtype": sorter.expected_subtype,
                 "predicted subtype": sorter.contract_subtype,
                 "doc type ok": sorter.doc_type_ok,
                 "subtype ok": sorter.subtype_ok,
                 truncated: sorter.truncated,
               })}</div>
               ${sorter.reasoning ? `<div class="reasoning" style="margin-top:6px">${esc(sorter.reasoning)}</div>` : ""}
             </td></tr>`
        : task === "chained_sorter_extractor"
          ? `<tr class="insight-row" data-expand="${i}" hidden>
               <td colspan="5">
                 <div class="kv" style="max-width:760px">${kvRowsTyped({
                   "sorter subtype": sorter.contract_subtype,
                   "expected subtype": sorter.expected_subtype,
                   "sorter doc type ok": sorter.doc_type_ok,
                   "sorter subtype ok": sorter.subtype_ok,
                   confidence: sorter.confidence,
                 })}</div>
                 ${sorter.reasoning ? `<div class="reasoning" style="margin-top:6px">${esc(sorter.reasoning)}</div>` : ""}
               </td></tr>`
          : `<tr class="insight-row" data-expand="${i}" hidden>
               <td colspan="5">
                 <div class="score-rows" style="max-width:560px">${scoreRows(res.field_scores)}</div>
                 ${res.ambiguous_fields?.length ? `<div class="soft" style="margin-top:6px">ambiguous fields: <span class="mono">${esc(res.ambiguous_fields.join(", "))}</span></div>` : ""}
                 ${res.error ? `<div class="reasoning" style="margin-top:6px">${esc(res.error)}</div>` : ""}
               </td></tr>`;
      const status = res.status === "completed"
        ? '<span class="badge" style="color:var(--good);border-color:#b7e0c5;background:#eef8f1">ok</span>'
        : `<span class="badge" style="color:var(--bad);border-color:#f2c8c8;background:#fdf0f0">${esc(res.status)}</span>`;
      const score = task === "contract_entity_extraction"
        ? res.overall_score
        : task === "chained_sorter_extractor"
          ? res.extractor_scores?.overall_extraction_score ?? res.overall_score
          : res.sorter?.subtype_ok === true ? 1 : res.sorter?.subtype_ok === false ? 0 : null;
      const scoreCell = score == null ? '<span class="faint">—</span>'
        : `${fmt.score(score)}${barHtml(score)}`;
      const toks = task === "subtype_classification"
        ? res.sorter_tokens?.total_tokens
        : task === "chained_sorter_extractor"
          ? (res.sorter_tokens?.total_tokens ?? 0) + (res.extractor_tokens?.total_tokens ?? 0)
          : res.tokens?.total_tokens;
      const name = task === "contract_entity_extraction"
        ? res.filename
        : (res.filename || "").split("_").slice(-2).join(" ");
      return `<tr data-expand-row="${i}">
        <td class="mono" style="max-width:380px;overflow-wrap:anywhere">${esc(name)}</td>
        <td>${status}</td>
        <td>${scoreCell}</td>
        <td class="num">${fmt.tokens(toks)}</td>
        <td class="num">${fmt.int(res.tokens?.prompt_tokens ?? res.sorter_tokens?.prompt_tokens ?? null)}</td>
      </tr>${detail}`;
    })
    .join("");
  return `<div class="table-wrap"><table class="data">
    <thead><tr>
      <th>Document</th><th>Status</th><th>Score</th><th class="num">Tokens</th><th class="num">Prompt tokens</th>
    </tr></thead><tbody>${rows}</tbody></table></div>`;
}

function confusionMatrix(cm) {
  const subtypes = Object.keys(cm || {}).sort();
  if (!subtypes.length) return "";
  const cells = subtypes
    .map(
      (expected) =>
        `<tr><td class="mono">${esc(expected)}</td>` +
        subtypes
          .map((predicted) => {
            const count = cm[expected][predicted] || 0;
            const isDiag = expected === predicted;
            const cls = isDiag
              ? count > 0 ? 'style="background:#eef8f1;color:var(--good)"' : ""
              : count > 0 ? 'style="background:#fdf0f0;color:var(--bad)"' : "";
            return `<td class="num" ${cls}>${count || "·"}</td>`;
          })
          .join("") +
        `</tr>`
    )
    .join("");
  const head = subtypes.map((s) => `<th class="mono">${esc(s)}</th>`).join("");
  return `<div class="table-wrap" style="max-height:420px;overflow:auto"><table class="data">
    <thead><tr><th class="mono">expected \\ predicted</th>${head}</tr></thead>
    <tbody>${cells}</tbody></table></div>`;
}

function promptString(run) {
  if (run.prompt_version) return run.prompt_version;
  const pv = run.prompt_versions;
  if (pv && typeof pv === "object") return Object.values(pv).join(" + ");
  return null;
}

async function renderRun(id) {
  const run = await fetchJson(`data/runs/${String(id).padStart(3, "0")}.json`);
  state.runId = id;
  const task = run.task;
  const tokens = run.tokens || {};
  const scores = run.scores || {};
  const headline = headlineCell((state.index.find((r) => r.id === id) || {}).headline);
  const sorter = task === "subtype_classification" ? scores.sorter || {} : null;
  const extractor = task === "contract_entity_extraction" ? scores : scores.extractor || {};
  const dataSource = run.data_source || {};
  const git = run.git || {};

  const cards = [];
  if (task === "subtype_classification") {
    cards.push({ k: "Strict accuracy", v: fmt.score(sorter.exact_match), d: "exact CUAD subtype" });
    cards.push({ k: "Equiv accuracy", v: fmt.score(sorter.subtype_accuracy), d: "equivalent family" });
    cards.push({ k: "Confidence", v: fmt.score(sorter.confidence), d: "mean model confidence" });
    cards.push({ k: "Failed rows", v: fmt.int(sorter.failure_insights?.n_failed), d: Object.entries(sorter.failure_insights?.mode_counts || {}).map(([m, n]) => `${m} ×${n}`).join(" · ") });
  } else if (task === "chained_sorter_extractor") {
    cards.push({ k: "Sorter exact match", v: fmt.score(scores.sorter?.exact_match), d: "doc_type" });
    cards.push({ k: "Extractor score", v: fmt.score(extractor.overall_extraction_score), d: "overall extraction" });
    cards.push({ k: "Verified precision", v: fmt.score(extractor.overall_verified_precision), d: "grounded items" });
    cards.push({ k: "Field presence", v: fmt.score(extractor.field_presence) });
  } else {
    cards.push({ k: "Overall extraction", v: fmt.score(scores.overall_extraction_score), d: "composite" });
    cards.push({ k: "Field presence", v: fmt.score(scores.field_presence) });
    cards.push({ k: "Schema valid", v: fmt.score(scores.schema_valid) });
    cards.push({ k: "Errors", v: fmt.int(run.n_error), d: `of ${fmt.int(run.n_rows)} rows` });
  }

  const sections = [];

  sections.push(`
    <div class="score-grid">${cards.map((c) => `<div class="stat"><div class="k">${esc(c.k)}</div><div class="v">${esc(c.v)}</div>${c.d ? `<div class="d">${esc(c.d)}</div>` : ""}</div>`).join("")}</div>`);

  sections.push(kvCard("Run metadata", `
    <table class="kv">${kvRowsTyped({
      timestamp: run.timestamp,
      experiment: run.experiment_name,
      task,
      model: run.model,
      prompts: promptString(run),
      "git commit": git.commit ? `${git.commit}${git.dirty ? " (dirty)" : ""}` : null,
      "data source": dataSource.project,
      "rows / ok / errors": `${run.n_rows} / ${run.n_ok} / ${run.n_error}`,
      seed: dataSource.seed,
      "n samples": dataSource.n_samples,
      fingerprint: dataSource.dataset_fingerprint,
    })}</table>`));

  sections.push(kvCard("Parameters", `<table class="kv">${kvRowsTyped(run.parameters)}</table>`));
  sections.push(kvCard("Tokens & cost", `
    <table class="kv">${kvRowsTyped({
      "prompt tokens": tokens.prompt_tokens ?? tokens.total?.prompt_tokens,
      "completion tokens": tokens.completion_tokens ?? tokens.total?.completion_tokens,
      "total tokens": tokens.total_tokens ?? tokens.total?.total_tokens,
      "cost (usd)": tokens.cost_usd ?? tokens.total?.cost_usd,
      "rows with usage": tokens.rows_with_usage ?? tokens.total?.rows_with_usage,
    })}</table>`));

  if (task === "contract_entity_extraction") {
    sections.push(kvCard("Scores", `
      <div style="max-width:560px">
        <div class="score-row"><div class="name">overall extraction</div>
          <div class="track"><i class="${barClass(scores.overall_extraction_score)}" style="width:${(scores.overall_extraction_score * 100).toFixed(1)}%"></i></div>
          <div class="value">${fmt.score(scores.overall_extraction_score)}</div></div>
        ${scoreRows(scores.per_field)}
      </div>`));
  } else if (task === "chained_sorter_extractor") {
    sections.push(kvCard("Sorter scores", `<div style="max-width:560px">${scoreRows(scores.sorter)}</div>`));
    sections.push(kvCard("Extractor scores", `<div style="max-width:560px">${scoreRows(extractor)}</div>`));
  } else {
    sections.push(kvCard("Sorter scores", `<div style="max-width:560px">${scoreRows({
      "exact match": sorter.exact_match,
      "subtype accuracy (equiv)": sorter.subtype_accuracy,
      confidence: sorter.confidence,
    })}</div>`));
    const perSubtype = sorter.per_subtype || {};
    const keys = Object.keys(perSubtype).sort();
    sections.push(kvCard("Per-subtype accuracy", `
      <div class="table-wrap"><table class="data">
        <thead><tr><th>Subtype</th><th class="num">Accuracy</th><th class="num">Correct</th><th class="num">Total</th><th style="width:30%"></th></tr></thead>
        <tbody>${keys.map((k) => `<tr><td class="mono">${esc(k)}</td><td class="num">${fmt.score(perSubtype[k].accuracy)}</td><td class="num">${fmt.int(perSubtype[k].correct)}</td><td class="num">${fmt.int(perSubtype[k].total)}</td><td>${barHtml(perSubtype[k].accuracy)}</td></tr>`).join("")}</tbody>
      </table></div>`));
    if (sorter.confusion_matrix) {
      sections.push(kvCard("Confusion matrix", confusionMatrix(sorter.confusion_matrix)));
    }
    const fi = sorter.failure_insights || {};
    const failures = (fi.failures || [])
      .map(
        (f) => `<tr class="insight-row">
          <td class="mono" style="max-width:340px;overflow-wrap:anywhere">${esc(f.filename)}</td>
          <td class="mono">${esc(f.expected)}</td>
          <td class="mono">${esc(f.predicted)}</td>
          <td><span class="mode-chip">${esc(f.mode)}</span></td>
          <td>${f.equiv_recovered ? '<span class="badge" style="color:var(--good)">recovered</span>' : ""}</td>
        </tr>
        <tr class="insight-row"><td></td><td colspan="4"><div class="reasoning">${esc(f.reasoning)}</div></td></tr>`
      )
      .join("");
    if (failures) {
      sections.push(kvCard(`Failed classification insights (${fmt.int(fi.n_failed)})`, `
        <div class="table-wrap"><table class="data">
          <thead><tr><th>Document</th><th>Expected</th><th>Predicted</th><th>Mode</th><th></th></tr></thead>
          <tbody>${failures}</tbody></table></div>`));
    }
  }

  sections.push(kvCard(`Per-document results (${fmt.int(run.n_rows)})`, resultsTable(run)));

  $("#view").innerHTML = `
    <a class="back" href="#/">← All runs</a>
    <div class="detail-head">
      <h2><span class="mono">${esc(run.experiment_name)}</span></h2>
      <div class="meta-line">${taskTag(task)} · ${esc(run.model)} · run #${id} · ${fmt.date(run.timestamp)} · ${headline}</div>
    </div>
    ${sections.join("")}`;

  $("#view").addEventListener("click", (e) => {
    const tr = e.target.closest("tr[data-expand-row]");
    if (!tr) return;
    const detailRow = document.querySelector(`tr[data-expand="${tr.dataset.expandRow}"]`);
    if (detailRow) detailRow.hidden = !detailRow.hidden;
  });
  window.scrollTo(0, 0);
}

/* ---------- boot ---------- */

async function boot() {
  try {
    const [meta, index] = await Promise.all([
      fetchJson("data/meta.json"),
      fetchJson("data/index.json"),
    ]);
    state.meta = meta;
    state.index = index;
    const built = new Date(meta.built_at).toISOString().replace("T", " ").slice(0, 16);
    $("#build-time").textContent = `generated ${built} UTC from ${meta.source} · `;
    window.addEventListener("hashchange", route);
    await route();
  } catch (err) {
    $("#view").innerHTML =
      `<div class="empty">Could not load experiment data (${esc(err.message)}).<br>
       Regenerate with <span class="mono">python scripts/site/build_site.py</span>.</div>`;
  }
}

document.addEventListener("DOMContentLoaded", boot);
